#include "RackState.h"
#include <cassert>
#include <limits>
int main(){ml::RackState a;a.analysisSource=2;a.deltaListen=true;ml::SavedModule m;m.instance=7;m.typeHi=8;m.typeLo=9;m.version=3;m.lane=4;m.slot=8;m.bypass=true;m.parameters={{2,1.25},{7,-3}};m.opaque={1,2,3,4};a.modules.push_back(m);std::vector<uint8_t> data;assert(ml::RackStateCodec::encode(a,data));ml::RackState b;assert(ml::RackStateCodec::decode(data.data(),data.size(),b));assert(a==b);auto legacy=a;legacy.format=1;assert(ml::RackStateCodec::encode(legacy,data));assert(ml::RackStateCodec::decode(data.data(),data.size(),b));assert(b.format==2&&b.modules[0].slot==4&&b.modules[0].lane==4);
 auto bad=a;bad.modules.push_back(m);assert(!ml::RackStateCodec::encode(bad,data));bad=a;bad.modules[0].parameters[0].value=std::numeric_limits<double>::quiet_NaN();assert(!ml::RackStateCodec::encode(bad,data));bad=a;bad.modules[0].parameters.push_back(bad.modules[0].parameters[0]);assert(!ml::RackStateCodec::encode(bad,data));assert(ml::RackStateCodec::encode(a,data));data.push_back(0);assert(!ml::RackStateCodec::decode(data.data(),data.size(),b));data.resize(8);assert(!ml::RackStateCodec::decode(data.data(),data.size(),b));}
